function sha256Hex(str) {
  const bytes = [];
  for (const ch of String(str)) {
    const c = ch.codePointAt(0);
    if (c < 0x80) bytes.push(c);
    else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else bytes.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  const K = [], H = [];
  const frac = x => ((x - Math.floor(x)) * 4294967296) | 0;
  for (let n = 2, found = 0; found < 64; n++) {
    let prime = true;
    for (let d = 2; d * d <= n; d++) if (n % d === 0) { prime = false; break; }
    if (prime) { if (found < 8) H.push(frac(Math.pow(n, 1 / 2))); K.push(frac(Math.pow(n, 1 / 3))); found++; }
  }
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const hi = Math.floor(bitLen / 4294967296);
  bytes.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255);
  bytes.push((bitLen >>> 24) & 255, (bitLen >>> 16) & 255, (bitLen >>> 8) & 255, bitLen & 255);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  const w = new Array(64);
  for (let off = 0; off < bytes.length; off += 64) {
    for (let t = 0; t < 16; t++) w[t] = (bytes[off + 4 * t] << 24) | (bytes[off + 4 * t + 1] << 16) | (bytes[off + 4 * t + 2] << 8) | bytes[off + 4 * t + 3];
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      const s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) | 0;
    }
    let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (let t = 0; t < 64; t++) {
      const t1 = (h + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[t] + w[t]) | 0;
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  return H.map(x => (x >>> 0).toString(16).padStart(8, '0')).join('');
}

// Works out the ONE action each changed row needs. The database decides whether it is allowed.
const norm = v => String(v == null ? '' : v).trim().toLowerCase();
const str = v => String(v == null ? '' : v).trim();
const STAGES = {
  'Needs Human Verification': { action: 'record_verification', col: 'Verification_Decision', actorCol: 'Verifier_ID', label: 'verification', notify: 'admin', help: 'Verified or Rejected',
    map: { verified: 'verified', verify: 'verified', approve: 'verified', approved: 'verified', yes: 'verified', reject: 'rejected', rejected: 'rejected', no: 'rejected' } },
  'Pending Review': { action: 'record_reviewer_decision', col: 'Reviewer_Decision', actorCol: 'Reviewer_ID', label: 'reviewer', notify: 'reviewer', help: 'Approve, Reject or Revise',
    map: { approve: 'approved', approved: 'approved', yes: 'approved', reject: 'rejected', rejected: 'rejected', no: 'rejected', revise: 'revision_requested', revision: 'revision_requested', 'request revision': 'revision_requested', 'revision requested': 'revision_requested', changes: 'revision_requested' } },
  'Reviewer Approved': { action: 'record_publisher_authorization', col: 'Publisher_Authorization', actorCol: 'Publisher_ID', label: 'publisher', notify: 'publisher', help: 'Authorize or Decline',
    map: { authorize: 'authorized', authorized: 'authorized', authorise: 'authorized', authorised: 'authorized', approve: 'authorized', approved: 'authorized', yes: 'authorized', decline: 'declined', declined: 'declined', reject: 'declined', rejected: 'declined', no: 'declined', deny: 'declined' } },
  'Awaiting Admin Approval': { action: 'record_admin_decision', col: 'Admin_Approval', actorCol: 'Admin_ID', label: 'admin', notify: 'admin', help: 'Approve or Reject',
    map: { approve: 'approved', approved: 'approved', yes: 'approved', reject: 'rejected', rejected: 'rejected', no: 'rejected' } }
};
const EDIT_LOCKED = ['Superseded', 'Publishing', 'Published', 'Reconciliation Required'];
const DECISION_COLS = ['Verification_Decision', 'Reviewer_Decision', 'Publisher_Authorization', 'Admin_Approval'];
const WF = 'LinkedIn Content - Approval Manager';
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const r = items[i].json;
  if (!str(r.Content_ID)) continue;
  const text = String(r.Post_Text == null ? '' : r.Post_Text);
  const liveHash = sha256Hex(text);
  const knownHash = norm(r.Content_Hash);
  const status = str(r.Review_Status);
  const chats = { reviewer: str(r.cfg_reviewer_chat), publisher: str(r.cfg_publisher_chat), admin: str(r.cfg_admin_chat) };
  const base = {
    row_number: r.row_number, Post_ID: str(r.Post_ID), Content_ID: str(r.Content_ID), Version: Number(r.Version) || 1,
    Destination: str(r.Destination), Language: str(r.Language), Topic: str(r.Topic), Pillar: str(r.Pillar), Variation: str(r.Variation), Angle: str(r.Angle),
    Post_Text: text, Sources_Used: str(r.Sources_Used), All_Sources: str(r.All_Sources), Visual_Recommendation: str(r.Visual_Recommendation),
    Risk_Level: str(r.Risk_Level), Risk_Notes: str(r.Risk_Notes), Admin_Approval_Required: str(r.Admin_Approval_Required) || 'No', Risk_Flags: str(r.Risk_Flags),
    Risk_Hash: str(r.Risk_Hash), Risk_Checked_At: str(r.Risk_Checked_At), Risk_Review_Status: str(r.Risk_Review_Status),
    Reviewer_Notes: str(r.Reviewer_Notes), Reviewer_ID: str(r.Reviewer_ID),
    old_status: status, Review_Status: status, Content_Hash: str(r.Content_Hash), Approved_Hash: str(r.Approved_Hash), Approved_At: str(r.Approved_At),
    live_hash: liveHash, reviewer_chat: chats.reviewer, publisher_chat: chats.publisher, admin_chat: chats.admin
  };
  DECISION_COLS.forEach(c => { base[c] = str(r[c]); });
  const note = (msg, role) => out.push({ json: Object.assign({}, base, { kind: 'note', Status_Note: msg, notify_role: role, notify_chat: chats[role] || '' }), pairedItem: { item: i } });

  if (knownHash && knownHash !== liveHash) {
    const editor = str(r.Edited_By_ID);
    if (EDIT_LOCKED.includes(status)) { note('Post_Text was changed on a version that is ' + status + ' and can no longer change. Put the original text back; the database keeps the original.', 'admin'); continue; }
    if (!editor) { note('Post_Text was edited. Enter your user ID in Edited_By_ID so the edit is saved as a new version. Earlier approvals do not carry over.', 'reviewer'); continue; }
    if (!text.trim() || text.length > 1250) { note('Edited text is ' + text.length + ' characters. It must be 1 to 1,250 characters before it can be saved as a new version.', 'reviewer'); continue; }
    const root = base.Content_ID.replace(/-R[0-9]+$/, '');
    out.push({ json: {
      kind: 'edit', Post_ID: base.Post_ID, Content_ID: root + '-R' + (base.Version + 1), Destination: base.Destination, Language: base.Language, Topic: base.Topic,
      Pillar: base.Pillar, Variation: base.Variation, Angle: base.Angle, Post_Text: text, Visual_Recommendation: base.Visual_Recommendation,
      Sources_Used: base.Sources_Used, All_Sources: base.All_Sources, Risk_Level: base.Risk_Level, force_risk_check: true, Execution_ID: String($execution.id),
      rev_source: 'manual edit', rev_actor: editor, rev_parent_content_id: base.Content_ID, rev_parent_hash: knownHash, rev_parent_version: base.Version,
      rev_change_summary: 'Edited in the sheet by ' + editor, rev_old_row_number: base.row_number, rev_reviewer_chat: chats.reviewer, rev_admin_chat: chats.admin
    }, pairedItem: { item: i } });
    continue;
  }

  const stage = STAGES[status];
  if (!stage) continue;
  const raw = norm(r[stage.col]);
  if (!raw) continue;
  const decision = stage.map[raw];
  if (!decision) { note('"' + str(r[stage.col]) + '" in ' + stage.col + ' is not a recognised value. Use ' + stage.help + '.', stage.notify); continue; }
  const actor = str(r[stage.actorCol]);
  if (!actor) { note('Enter your user ID in ' + stage.actorCol + ' so the ' + stage.label + ' decision can be checked against the users directory.', stage.notify); continue; }
  const notes = stage.action === 'record_verification' ? str(r.Verification_Notes) : str(r.Reviewer_Notes);
  if (stage.action === 'record_verification' && !notes) { note('Add what you checked in Verification_Notes before verifying.', 'admin'); continue; }
  if (decision === 'revision_requested' && !notes) { note('Add what should change in Reviewer_Notes, then set Reviewer_Decision to Revise again.', 'reviewer'); continue; }

  out.push({ json: Object.assign({}, base, {
    kind: 'decision', stage_col: stage.col, stage_label: stage.label, stage_notify: stage.notify, actor_user_id: actor,
    gw: {
      action: stage.action, content_id: base.Content_ID, content_hash: knownHash || liveHash, actor_user_id: actor, actor_channel: 'google_sheets',
      decision, notes, execution_id: String($execution.id), workflow_name: WF,
      evidence: stage.action === 'record_verification' ? { notes, source: 'Content Variations sheet', sheet_row: r.row_number } : {}
    }
  }), pairedItem: { item: i } });
}
return out;

// Turns the database answer into the sheet mirror and the next notification.
const REFUSED = {
  not_found: 'this Content_ID is not in the database.',
  superseded: 'this version has been replaced by a newer one. Act on the newest row.',
  hash_mismatch: 'the text in the sheet differs from the version stored in the database. Fill Edited_By_ID to save your edit as a new version, or restore the original text.',
  actor_not_authorized: 'user ID {actor} has no active {label} role for {dest} in the users directory.',
  invalid_transition: 'the database shows this version as "{db}", so a {label} decision does not apply now.',
  not_approval_eligible: 'the independent risk review did not complete, so this version must be verified before it can be approved.',
  human_verification_required: 'human verification of this exact text is required first.',
  self_approval_blocked: 'the same person cannot act at two approval stages unless the Admin allows self-approval for that user.',
  over_character_limit: 'the post is over 1,250 characters.'
};
const NEXT = {
  'Pending Review': ['reviewer', 'Verified by a human. Ready for the reviewer decision.'],
  'Reviewer Approved': ['publisher', 'Reviewer approved this exact text. Publisher authorization needed.'],
  'Awaiting Admin Approval': ['admin', 'High or Critical risk. Admin approval needed before it can be scheduled.'],
  'Approved - Ready to Schedule': ['publisher', 'All required approvals are recorded for this exact text. It can be picked for the next matching slot once publishing is enabled.'],
  'Rejected': ['reviewer', 'Rejected at the {label} stage.'],
  'Revision Requested': ['', 'Revision requested. A new version is being written.']
};
const stamp = () => DateTime.now().setZone('Asia/Kolkata').toFormat('yyyy-MM-dd HH:mm');
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const res = items[i].json || {};
  if (res.kind === 'note') { out.push({ json: Object.assign({}, res, { start_revision: false }), pairedItem: { item: i } }); continue; }
  const req = $('Evaluate Approval State').itemMatching(i).json;
  const fill = s => String(s).split('{actor}').join(req.actor_user_id).split('{label}').join(req.stage_label).split('{dest}').join(req.Destination).split('{db}').join(String(res.old_status || 'unknown'));
  const o = Object.assign({}, req);
  delete o.gw;
  o.start_revision = false;
  let role = '';
  if (res.error || typeof res.success !== 'boolean') {
    const why = res.error ? String(res.error.message || res.error) : 'no response';
    o.Status_Note = 'Decision NOT recorded: the database call failed (' + why.slice(0, 200) + '). Nothing changed. Re-enter the decision to try again.';
    role = 'admin';
  } else if (res.duplicate) {
    continue;
  } else if (res.success) {
    o.Review_Status = String(res.new_status || '');
    o.Content_Hash = req.gw.content_hash;
    const next = NEXT[o.Review_Status] || ['', ''];
    role = next[0];
    o.Status_Note = fill(next[1]) + ' (' + req.stage_label + ': ' + req.actor_user_id + ', ' + stamp() + ')';
    if (res.approved_hash) { o.Approved_Hash = String(res.approved_hash); o.Approved_At = stamp(); }
    o.start_revision = o.Review_Status === 'Revision Requested';
  } else {
    if (res.new_status) o.Review_Status = String(res.new_status);
    o.Status_Note = 'Not recorded: ' + fill(REFUSED[res.outcome] || ('refused by the database (' + res.outcome + ').'));
    o[req.stage_col] = '';
    role = ['actor_not_authorized', 'self_approval_blocked', 'not_found'].includes(res.outcome) ? 'admin' : req.stage_notify;
  }
  o.notify_role = role;
  o.notify_chat = role ? String(req[role + '_chat'] || '') : '';
  out.push({ json: o, pairedItem: { item: i } });
}
return out;

