// AI revision -> candidate new version (saved only if the database accepts it).
const NL = String.fromCharCode(10);
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const prev = $('Interpret Decision Result').itemMatching(i).json;
  const o = $('Revise Post').itemMatching(i).json.output || {};
  if (!o.hook || !o.body) throw new Error('Malformed revision output for ' + prev.Content_ID);
  const tags = (o.hashtags || []).map(h => String(h).startsWith('#') ? String(h) : '#' + h).join(' ');
  const text = [o.hook, o.body, o.cta, tags].filter(Boolean).join(NL + NL);
  const version = (Number(prev.Version) || 1) + 1;
  const root = String(prev.Content_ID).replace(/-R[0-9]+$/, '');
  out.push({
    json: {
      Post_ID: prev.Post_ID, Content_ID: root + '-R' + version, Destination: prev.Destination, Language: prev.Language, Topic: prev.Topic,
      Pillar: prev.Pillar, Variation: prev.Variation, Angle: prev.Angle, Post_Text: text, Visual_Recommendation: prev.Visual_Recommendation,
      Sources_Used: prev.Sources_Used, All_Sources: prev.All_Sources, Risk_Level: prev.Risk_Level, force_risk_check: true, Execution_ID: String($execution.id),
      rev_source: 'ai revision', rev_actor: prev.actor_user_id, rev_parent_content_id: prev.Content_ID, rev_parent_hash: prev.Content_Hash,
      rev_parent_version: Number(prev.Version) || 1, rev_change_summary: String(o.change_summary || ''), rev_old_row_number: prev.row_number,
      rev_reviewer_chat: prev.reviewer_chat, rev_admin_chat: prev.admin_chat
    },
    pairedItem: { item: i }
  });
}
return out;

function sha256Hex(str) {
  const bytes = [];
  for (const ch of String(str)) {
    const c = ch.codePointAt(0);
    if (c < 0x80) bytes.push(c);
    else if (c < 0x800) bytes.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) bytes.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else bytes.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  const K = [], H = [];
  const frac = x => ((x - Math.floor(x)) * 4294967296) | 0;
  for (let n = 2, found = 0; found < 64; n++) {
    let prime = true;
    for (let d = 2; d * d <= n; d++) if (n % d === 0) { prime = false; break; }
    if (prime) { if (found < 8) H.push(frac(Math.pow(n, 1 / 2))); K.push(frac(Math.pow(n, 1 / 3))); found++; }
  }
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const hi = Math.floor(bitLen / 4294967296);
  bytes.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255);
  bytes.push((bitLen >>> 24) & 255, (bitLen >>> 16) & 255, (bitLen >>> 8) & 255, bitLen & 255);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  const w = new Array(64);
  for (let off = 0; off < bytes.length; off += 64) {
    for (let t = 0; t < 16; t++) w[t] = (bytes[off + 4 * t] << 24) | (bytes[off + 4 * t + 1] << 16) | (bytes[off + 4 * t + 2] << 8) | bytes[off + 4 * t + 3];
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      const s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) | 0;
    }
    let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (let t = 0; t < 64; t++) {
      const t1 = (h + (rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)) + ((e & f) ^ (~e & g)) + K[t] + w[t]) | 0;
      const t2 = ((rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  return H.map(x => (x >>> 0).toString(16).padStart(8, '0')).join('');
}

// Database accepted the new version: build the sheet rows that mirror it.
const stamp = DateTime.now().setZone('Asia/Kolkata').toFormat('yyyy-MM-dd HH:mm');
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const res = items[i].json;
  const d = $('Check Revision Risk').itemMatching(i).json;
  const text = String(d.Post_Text || '');
  const status = String(res.new_status || 'Pending Review');
  const verify = status === 'Needs Human Verification';
  out.push({
    json: {
      Post_ID: d.Post_ID, Content_ID: d.Content_ID, Parent_Content_ID: d.rev_parent_content_id, Version: res.new_version || (d.rev_parent_version + 1),
      Destination: d.Destination, Language: d.Language, Topic: d.Topic, Pillar: d.Pillar, Variation: d.Variation, Angle: d.Angle,
      Post_Text: text, Char_Count: text.length, Within_Limit: text.length <= 1250 ? 'Yes' : 'NO - needs edit',
      Risk_Level: d.Risk_Level || '', Risk_Notes: d.Risk_Notes || '', Admin_Approval_Required: d.Admin_Approval_Required || 'No', Risk_Flags: d.Risk_Flags || '',
      Risk_Hash: d.Risk_Hash || '', Risk_Checked_At: d.Risk_Checked_At || '', Risk_Review_Status: d.Risk_Review_Status || '', Approval_Eligible: d.Approval_Eligible || 'No',
      Visual_Recommendation: d.Visual_Recommendation || '', Sources_Used: d.Sources_Used || '', All_Sources: d.All_Sources || '',
      Review_Status: status,
      Status_Note: (d.rev_source === 'manual edit' ? 'Manual edit' : 'AI revision') + ' of ' + d.rev_parent_content_id + ': ' + String(d.rev_change_summary || '').slice(0, 300) + (verify ? ' | Human verification needed before review.' : ''),
      Content_Hash: sha256Hex(text), Generated_At: stamp, Execution_ID: String($execution.id),
      old_row_number: d.rev_old_row_number, reviewer_chat: d.rev_reviewer_chat, admin_chat: d.rev_admin_chat, rev_source: d.rev_source, change_summary: d.rev_change_summary
    },
    pairedItem: { item: i }
  });
}
return out;

